#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Specificity(u16, u16, u16);

#[derive(Debug, Clone)]
struct SimpleSelector {
    tag: Option<String>,
    id: Option<String>,
    classes: Vec<String>,
    attrs: Vec<AttrSelector>,
    pseudos: Vec<PseudoClass>,
}

impl SimpleSelector {
    fn matches_with_pseudo(&self, element: &ElementInfo, pseudo: PseudoTarget) -> bool {
        if let Some(tag) = &self.tag {
            if tag != "*" && tag != &element.tag {
                return false;
            }
        }
        if let Some(id) = &self.id {
            if element.id.as_deref() != Some(id.as_str()) {
                return false;
            }
        }
        for class in &self.classes {
            if !element.classes.iter().any(|c| c == class) {
                return false;
            }
        }
        for attr in &self.attrs {
            if !attr.matches(element) {
                return false;
            }
        }
        for pseudo_class in &self.pseudos {
            if !pseudo_class.matches_with_pseudo(element, pseudo) {
                return false;
            }
        }
        true
    }

    fn specificity(&self) -> Specificity {
        let mut id_count = self.id.as_ref().map(|_| 1).unwrap_or(0);
        let mut class_count = (self.classes.len() + self.attrs.len()) as u16;
        let mut tag_count = self
            .tag
            .as_ref()
            .filter(|tag| tag.as_str() != "*")
            .map(|_| 1)
            .unwrap_or(0);

        for pseudo in &self.pseudos {
            match pseudo {
                PseudoClass::Not(inner) | PseudoClass::Is(inner) => {
                    let inner_spec = inner
                        .iter()
                        .map(SimpleSelector::specificity)
                        .max()
                        .unwrap_or(Specificity(0, 0, 0));
                    id_count += inner_spec.0;
                    class_count += inner_spec.1;
                    tag_count += inner_spec.2;
                }
                // Selectors inside :where() intentionally contribute no specificity.
                PseudoClass::Where(_) => {}
                _ => {
                    class_count += 1;
                }
            }
        }

        Specificity(id_count, class_count, tag_count)
    }
}

#[derive(Debug, Clone)]
enum PseudoClass {
    Root,
    FirstChild,
    LastChild,
    FirstOfType,
    LastOfType,
    NthChildEven,
    NthChildOdd,
    NthChild(usize),
    NthChildFormula { a: i32, b: i32 },
    NthOfTypeEven,
    NthOfTypeOdd,
    NthOfType(usize),
    NthOfTypeFormula { a: i32, b: i32 },
    Hover,
    Before,
    After,
    Marker,
    FirstLetter,
    Unsupported,
    Not(Vec<SimpleSelector>),
    Is(Vec<SimpleSelector>),
    Where(Vec<SimpleSelector>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum PseudoTarget {
    None,
    Before,
    After,
    Marker,
    FirstLetter,
}

impl PseudoClass {
    fn is_positional(&self) -> bool {
        matches!(
            self,
            PseudoClass::FirstChild
                | PseudoClass::LastChild
                | PseudoClass::FirstOfType
                | PseudoClass::LastOfType
                | PseudoClass::NthChildEven
                | PseudoClass::NthChildOdd
                | PseudoClass::NthChild(_)
                | PseudoClass::NthChildFormula { .. }
                | PseudoClass::NthOfTypeEven
                | PseudoClass::NthOfTypeOdd
                | PseudoClass::NthOfType(_)
                | PseudoClass::NthOfTypeFormula { .. }
        )
    }

    fn matches_with_pseudo(&self, element: &ElementInfo, pseudo: PseudoTarget) -> bool {
        match self {
            PseudoClass::Root => element.is_root,
            PseudoClass::FirstChild => element.child_index == 1,
            PseudoClass::LastChild => element.child_index == element.child_count,
            PseudoClass::FirstOfType => element.type_index == 1,
            PseudoClass::LastOfType => element.type_index == element.type_count,
            PseudoClass::NthChildEven => element.child_index % 2 == 0,
            PseudoClass::NthChildOdd => element.child_index % 2 == 1,
            PseudoClass::NthChild(n) => element.child_index == *n,
            PseudoClass::NthChildFormula { a, b } => nth_index_matches(element.child_index, *a, *b),
            PseudoClass::NthOfTypeEven => element.type_index % 2 == 0,
            PseudoClass::NthOfTypeOdd => element.type_index % 2 == 1,
            PseudoClass::NthOfType(n) => element.type_index == *n,
            PseudoClass::NthOfTypeFormula { a, b } => nth_index_matches(element.type_index, *a, *b),
            PseudoClass::Hover => false,
            PseudoClass::Before => matches!(pseudo, PseudoTarget::Before),
            PseudoClass::After => matches!(pseudo, PseudoTarget::After),
            PseudoClass::Marker => matches!(pseudo, PseudoTarget::Marker),
            PseudoClass::FirstLetter => matches!(pseudo, PseudoTarget::FirstLetter),
            PseudoClass::Unsupported => false,
            PseudoClass::Not(selectors) => !selectors
                .iter()
                .any(|selector| selector.matches_with_pseudo(element, pseudo)),
            PseudoClass::Is(selectors) | PseudoClass::Where(selectors) => selectors
                .iter()
                .any(|selector| selector.matches_with_pseudo(element, pseudo)),
        }
    }

    fn has_positional_pseudo(&self) -> bool {
        if self.is_positional() {
            return true;
        }
        match self {
            PseudoClass::Not(selectors)
            | PseudoClass::Is(selectors)
            | PseudoClass::Where(selectors) => selectors.iter().any(|selector| {
                selector
                    .pseudos
                    .iter()
                    .any(PseudoClass::has_positional_pseudo)
            }),
            _ => false,
        }
    }

    fn pseudo_target(&self) -> Option<PseudoTarget> {
        match self {
            PseudoClass::Before => Some(PseudoTarget::Before),
            PseudoClass::After => Some(PseudoTarget::After),
            PseudoClass::Marker => Some(PseudoTarget::Marker),
            PseudoClass::FirstLetter => Some(PseudoTarget::FirstLetter),
            PseudoClass::Not(selectors)
            | PseudoClass::Is(selectors)
            | PseudoClass::Where(selectors) => selectors
                .iter()
                .find_map(|selector| selector.pseudos.iter().find_map(PseudoClass::pseudo_target)),
            _ => None,
        }
    }
}

fn nth_index_matches(index: usize, a: i32, b: i32) -> bool {
    let index = index as i32;
    if a == 0 {
        return index == b;
    }
    if a > 0 {
        index >= b && (index - b) % a == 0
    } else {
        index <= b && (b - index) % (-a) == 0
    }
}

#[derive(Debug, Clone)]
struct AttrSelector {
    name: String,
    op: AttrOp,
    value: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AttrOp {
    Exists,
    Equals,
    Includes,
    DashMatch,
    Prefix,
    Suffix,
    Substring,
}

impl AttrSelector {
    fn matches(&self, element: &ElementInfo) -> bool {
        let Some(value) = element.attrs.get(&self.name) else {
            return false;
        };
        match self.op {
            AttrOp::Exists => true,
            AttrOp::Equals => self.value.as_deref().map(|v| value == v).unwrap_or(false),
            AttrOp::Includes => self
                .value
                .as_deref()
                .map(|v| value.split_whitespace().any(|part| part == v))
                .unwrap_or(false),
            AttrOp::DashMatch => self
                .value
                .as_deref()
                .map(|v| value == v || value.starts_with(&format!("{v}-")))
                .unwrap_or(false),
            AttrOp::Prefix => self
                .value
                .as_deref()
                .map(|v| value.starts_with(v))
                .unwrap_or(false),
            AttrOp::Suffix => self
                .value
                .as_deref()
                .map(|v| value.ends_with(v))
                .unwrap_or(false),
            AttrOp::Substring => self
                .value
                .as_deref()
                .map(|v| value.contains(v))
                .unwrap_or(false),
        }
    }
}

#[derive(Debug, Clone)]
enum Combinator {
    Descendant,
    Child,
    AdjacentSibling,
    GeneralSibling,
}

#[derive(Debug, Clone)]
struct SelectorPattern {
    parts: Vec<SimpleSelector>,
    combinators: Vec<Combinator>,
}

impl SelectorPattern {
    fn has_positional_pseudos(&self) -> bool {
        self.parts
            .iter()
            .any(|part| part.pseudos.iter().any(PseudoClass::has_positional_pseudo))
    }

    fn has_sibling_combinators(&self) -> bool {
        self.combinators.iter().any(|comb| {
            matches!(
                comb,
                Combinator::AdjacentSibling | Combinator::GeneralSibling
            )
        })
    }

    fn pseudo_target(&self) -> Option<PseudoTarget> {
        for part in &self.parts {
            for pseudo in &part.pseudos {
                if let Some(target) = pseudo.pseudo_target() {
                    return Some(target);
                }
            }
        }
        None
    }

    fn matches(&self, element: &ElementInfo, ancestors: &[ElementInfo]) -> bool {
        self.matches_with_pseudo(element, ancestors, PseudoTarget::None)
    }

    fn matches_with_pseudo(
        &self,
        element: &ElementInfo,
        ancestors: &[ElementInfo],
        pseudo: PseudoTarget,
    ) -> bool {
        if self.parts.is_empty() {
            return false;
        }
        let last = self.parts.last().expect("non-empty");
        if !last.matches_with_pseudo(element, pseudo) {
            return false;
        }

        if self.parts.len() == 1 {
            return true;
        }

        let mut current: &ElementInfo = element;
        let mut current_index = ancestors.len();
        for (idx, part) in self.parts[..self.parts.len() - 1].iter().rev().enumerate() {
            let comb_index = self.combinators.len().saturating_sub(1 + idx);
            let combinator = self
                .combinators
                .get(comb_index)
                .unwrap_or(&Combinator::Descendant);
            match combinator {
                Combinator::Child => {
                    if current_index == 0 {
                        return false;
                    }
                    current_index -= 1;
                    current = &ancestors[current_index];
                    if !part.matches_with_pseudo(current, pseudo) {
                        return false;
                    }
                }
                Combinator::Descendant => {
                    let mut found = false;
                    while current_index > 0 {
                        current_index -= 1;
                        let ancestor = &ancestors[current_index];
                        if part.matches_with_pseudo(ancestor, pseudo) {
                            current = ancestor;
                            found = true;
                            break;
                        }
                    }
                    if !found {
                        return false;
                    }
                }
                Combinator::AdjacentSibling => {
                    let Some(prev) = current.prev_siblings.last() else {
                        return false;
                    };
                    current = prev;
                    if !part.matches_with_pseudo(current, pseudo) {
                        return false;
                    }
                }
                Combinator::GeneralSibling => {
                    let mut found = false;
                    for prev in current.prev_siblings.iter().rev() {
                        if part.matches_with_pseudo(prev, pseudo) {
                            current = prev;
                            found = true;
                            break;
                        }
                    }
                    if !found {
                        return false;
                    }
                }
            }
        }
        true
    }

    fn specificity(&self) -> Specificity {
        let mut spec = Specificity(0, 0, 0);
        for part in &self.parts {
            let part_spec = part.specificity();
            spec.0 += part_spec.0;
            spec.1 += part_spec.1;
            spec.2 += part_spec.2;
        }
        spec
    }
}

#[derive(Debug, Clone)]
struct RuleEntry {
    selector: SelectorPattern,
    specificity: Specificity,
    order: usize,
    layer_order: Option<usize>,
    container_conditions: Vec<ContainerRuleCondition>,
    scope_conditions: Vec<ScopeRuleCondition>,
    delta: StyleDelta,
    selector_text: String,
}

impl RuleEntry {
    fn normal_layer_rank(&self) -> usize {
        self.layer_order.unwrap_or(usize::MAX)
    }

    fn important_layer_rank(&self, layer_count: usize) -> usize {
        match self.layer_order {
            Some(order) => layer_count.saturating_sub(order),
            None => 0,
        }
    }
}

