impl RevertLayerDelta {
    fn is_empty(&self) -> bool {
        !self.color
            && !self.background_color
            && !self.width
            && !self.height
            && !self.box_sizing
            && !self.display
            && !self.visibility
            && !self.position
            && !self.float_mode
            && !self.clear_mode
            && !self.z_index
            && !self.direction
            && !self.writing_mode
            && !self.opacity
            && !self.paint_filter
            && !self.backdrop_filter
            && !self.will_change_backdrop_root
            && !self.mask_backdrop_root
            && !self.clip_path
            && !self.box_shadow
            && !self.text_shadow
            && !self.text_decoration_line
            && !self.text_decoration_color
            && !self.text_decoration_thickness
            && !self.text_decoration_style
            && !self.text_emphasis_style
            && !self.text_emphasis_color
            && !self.text_emphasis_position
            && !self.text_underline_offset
            && !self.text_underline_position
            && !self.text_overflow
            && !self.text_indent
            && !self.letter_spacing
            && !self.word_spacing
            && !self.tab_size
            && !self.text_align
            && !self.text_align_last
            && !self.text_justify
            && !self.text_transform
            && !self.white_space
            && !self.text_wrap_mode
            && !self.text_wrap_style
            && !self.vertical_align
            && !self.list_style_type
            && !self.list_style_image
            && !self.list_style_position
            && !self.word_break
            && !self.line_break
            && !self.hyphens
            && !self.hyphenate_character
            && !self.mix_blend_mode
            && !self.isolation
            && !self.overflow_x
            && !self.overflow_y
            && !self.overflow_inline
            && !self.overflow_block
            && !self.outline_width
            && !self.outline_style
            && !self.outline_color
            && !self.outline_offset
            && self.margin.is_empty()
            && self.padding.is_empty()
            && self.border_color.is_empty()
            && self.border_width.is_empty()
            && self.border_style.is_empty()
            && self.inset.is_empty()
            && self.margin_logical.is_empty()
            && self.padding_logical.is_empty()
            && self.border_color_logical.is_empty()
            && self.border_width_logical.is_empty()
            && self.border_style_logical.is_empty()
            && self.inset_logical.is_empty()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BoxEdgeTarget {
    All,
    Top,
    Right,
    Bottom,
    Left,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LogicalBoxEdgeTarget {
    Inline,
    InlineStart,
    InlineEnd,
    Block,
    BlockStart,
    BlockEnd,
}

#[derive(Debug, Clone, Default)]
struct LogicalEdgeRevertDelta {
    inline_start: bool,
    inline_end: bool,
    block_start: bool,
    block_end: bool,
}

impl LogicalEdgeRevertDelta {
    fn is_empty(&self) -> bool {
        !self.inline_start && !self.inline_end && !self.block_start && !self.block_end
    }

    fn set(&mut self, target: LogicalBoxEdgeTarget) {
        match target {
            LogicalBoxEdgeTarget::Inline => {
                self.inline_start = true;
                self.inline_end = true;
            }
            LogicalBoxEdgeTarget::InlineStart => self.inline_start = true,
            LogicalBoxEdgeTarget::InlineEnd => self.inline_end = true,
            LogicalBoxEdgeTarget::Block => {
                self.block_start = true;
                self.block_end = true;
            }
            LogicalBoxEdgeTarget::BlockStart => self.block_start = true,
            LogicalBoxEdgeTarget::BlockEnd => self.block_end = true,
        }
    }

    fn clear(&mut self, target: LogicalBoxEdgeTarget) {
        match target {
            LogicalBoxEdgeTarget::Inline => {
                self.inline_start = false;
                self.inline_end = false;
            }
            LogicalBoxEdgeTarget::InlineStart => self.inline_start = false,
            LogicalBoxEdgeTarget::InlineEnd => self.inline_end = false,
            LogicalBoxEdgeTarget::Block => {
                self.block_start = false;
                self.block_end = false;
            }
            LogicalBoxEdgeTarget::BlockStart => self.block_start = false,
            LogicalBoxEdgeTarget::BlockEnd => self.block_end = false,
        }
    }
}

#[derive(Debug, Clone, Default)]
struct EdgeRevertDelta {
    top: bool,
    right: bool,
    bottom: bool,
    left: bool,
}

impl EdgeRevertDelta {
    fn is_empty(&self) -> bool {
        !self.top && !self.right && !self.bottom && !self.left
    }

    fn set(&mut self, target: BoxEdgeTarget) {
        match target {
            BoxEdgeTarget::All => {
                self.top = true;
                self.right = true;
                self.bottom = true;
                self.left = true;
            }
            BoxEdgeTarget::Top => self.top = true,
            BoxEdgeTarget::Right => self.right = true,
            BoxEdgeTarget::Bottom => self.bottom = true,
            BoxEdgeTarget::Left => self.left = true,
        }
    }

    fn clear(&mut self, target: BoxEdgeTarget) {
        match target {
            BoxEdgeTarget::All => {
                self.top = false;
                self.right = false;
                self.bottom = false;
                self.left = false;
            }
            BoxEdgeTarget::Top => self.top = false,
            BoxEdgeTarget::Right => self.right = false,
            BoxEdgeTarget::Bottom => self.bottom = false,
            BoxEdgeTarget::Left => self.left = false,
        }
    }
}

