fn physical_box_edge_target_from_border_target(target: BorderColorTarget) -> Option<BoxEdgeTarget> {
    match target {
        BorderColorTarget::All => Some(BoxEdgeTarget::All),
        BorderColorTarget::Top => Some(BoxEdgeTarget::Top),
        BorderColorTarget::Right => Some(BoxEdgeTarget::Right),
        BorderColorTarget::Bottom => Some(BoxEdgeTarget::Bottom),
        BorderColorTarget::Left => Some(BoxEdgeTarget::Left),
        BorderColorTarget::InlineStart
        | BorderColorTarget::InlineEnd
        | BorderColorTarget::BlockStart
        | BorderColorTarget::BlockEnd => None,
    }
}

fn logical_box_edge_target_from_border_target(
    target: BorderColorTarget,
) -> Option<LogicalBoxEdgeTarget> {
    match target {
        BorderColorTarget::InlineStart => Some(LogicalBoxEdgeTarget::InlineStart),
        BorderColorTarget::InlineEnd => Some(LogicalBoxEdgeTarget::InlineEnd),
        BorderColorTarget::BlockStart => Some(LogicalBoxEdgeTarget::BlockStart),
        BorderColorTarget::BlockEnd => Some(LogicalBoxEdgeTarget::BlockEnd),
        BorderColorTarget::All
        | BorderColorTarget::Top
        | BorderColorTarget::Right
        | BorderColorTarget::Bottom
        | BorderColorTarget::Left => None,
    }
}

fn set_revert_layer_border_color(delta: &mut StyleDelta, target: BorderColorTarget) -> bool {
    if let Some(edge) = physical_box_edge_target_from_border_target(target) {
        clear_delta_border_color(delta, target);
        delta.revert_layer.border_color.set(edge);
        return true;
    }
    if let Some(edge) = logical_box_edge_target_from_border_target(target) {
        clear_delta_logical_border_color(delta, edge);
        delta.revert_layer.border_color_logical.set(edge);
        return true;
    }
    false
}

fn clear_revert_layer_border_color(delta: &mut StyleDelta, target: BorderColorTarget) {
    if let Some(edge) = physical_box_edge_target_from_border_target(target) {
        delta.revert_layer.border_color.clear(edge);
    }
    if let Some(edge) = logical_box_edge_target_from_border_target(target) {
        delta.revert_layer.border_color_logical.clear(edge);
    }
}

fn clear_delta_border_color(delta: &mut StyleDelta, target: BorderColorTarget) {
    split_uniform_border_color_delta(delta);
    if let Some(edge) = physical_box_edge_target_from_border_target(target) {
        clear_delta_physical_border_color(delta, edge);
    }
    if let Some(edge) = logical_box_edge_target_from_border_target(target) {
        clear_delta_logical_border_color(delta, edge);
    }
}

fn split_uniform_border_color_delta(delta: &mut StyleDelta) {
    if let Some(spec) = delta.border_color.take() {
        if delta.border_top_color.is_none() {
            delta.border_top_color = Some(spec.clone());
        }
        if delta.border_right_color.is_none() {
            delta.border_right_color = Some(spec.clone());
        }
        if delta.border_bottom_color.is_none() {
            delta.border_bottom_color = Some(spec.clone());
        }
        if delta.border_left_color.is_none() {
            delta.border_left_color = Some(spec);
        }
    }
    if let Some(var) = delta.border_color_var.take() {
        if delta.border_top_color_var.is_none() {
            delta.border_top_color_var = Some(var.clone());
        }
        if delta.border_right_color_var.is_none() {
            delta.border_right_color_var = Some(var.clone());
        }
        if delta.border_bottom_color_var.is_none() {
            delta.border_bottom_color_var = Some(var.clone());
        }
        if delta.border_left_color_var.is_none() {
            delta.border_left_color_var = Some(var);
        }
    }
}

