fn apply_border_style_mask(style: &mut ComputedStyle) {
    if matches!(
        style.border_style.top,
        BorderLineStyle::None | BorderLineStyle::Hidden
    ) {
        style.border_width.top = LengthSpec::Absolute(Pt::ZERO);
    }
    if matches!(
        style.border_style.right,
        BorderLineStyle::None | BorderLineStyle::Hidden
    ) {
        style.border_width.right = LengthSpec::Absolute(Pt::ZERO);
    }
    if matches!(
        style.border_style.bottom,
        BorderLineStyle::None | BorderLineStyle::Hidden
    ) {
        style.border_width.bottom = LengthSpec::Absolute(Pt::ZERO);
    }
    if matches!(
        style.border_style.left,
        BorderLineStyle::None | BorderLineStyle::Hidden
    ) {
        style.border_width.left = LengthSpec::Absolute(Pt::ZERO);
    }
    if !style.outline_visible {
        style.outline_width = LengthSpec::Absolute(Pt::ZERO);
    }
    promote_uniform_border_color_from_active_edges(style);
}

fn is_effective_zero_border_width(spec: LengthSpec) -> bool {
    match spec {
        LengthSpec::Auto
        | LengthSpec::Content
        | LengthSpec::MinContent
        | LengthSpec::MaxContent
        | LengthSpec::FitContent
        | LengthSpec::Inherit
        | LengthSpec::Initial => true,
        LengthSpec::Absolute(value) => value == Pt::ZERO,
        LengthSpec::Percent(value) => value.abs() <= f32::EPSILON,
        LengthSpec::Em(value) => value.abs() <= f32::EPSILON,
        LengthSpec::Rem(value) => value.abs() <= f32::EPSILON,
        LengthSpec::Calc(calc) => {
            calc.abs == Pt::ZERO
                && calc.percent.abs() <= f32::EPSILON
                && calc.em.abs() <= f32::EPSILON
                && calc.rem.abs() <= f32::EPSILON
        }
    }
}

fn promote_uniform_border_color_from_active_edges(style: &mut ComputedStyle) {
    if style.border_color.is_some() {
        return;
    }
    let mut candidate: Option<Color> = None;
    let mut active_edges = 0usize;
    let edges = [
        (style.border_width.top, style.border_top_color),
        (style.border_width.right, style.border_right_color),
        (style.border_width.bottom, style.border_bottom_color),
        (style.border_width.left, style.border_left_color),
    ];
    for (width, color) in edges {
        if is_effective_zero_border_width(width) {
            continue;
        }
        active_edges += 1;
        let Some(edge_color) = color else {
            // Another active side still relies on fallback; keep border_color unset.
            return;
        };
        match candidate {
            Some(existing) if existing != edge_color => {
                // Active edges disagree; shorthand color is not uniform.
                return;
            }
            None => {
                candidate = Some(edge_color);
            }
            _ => {}
        }
    }
    if active_edges > 0 {
        style.border_color = candidate;
    }
}

fn resolve_custom_color(style: &ComputedStyle, expr: &str) -> Option<Color> {
    resolve_custom_color_expr_with_alpha(style, expr).map(|(color, _)| color)
}

fn resolve_text_decoration_thickness_expr(
    style: &ComputedStyle,
    expr: &str,
) -> Option<TextDecorationThicknessMode> {
    resolve_text_decoration_thickness_expr_inner(style, expr, 0)
}

fn resolve_text_decoration_thickness_expr_inner(
    style: &ComputedStyle,
    expr: &str,
    depth: usize,
) -> Option<TextDecorationThicknessMode> {
    if depth > 12 {
        return None;
    }
    let expr = expr.trim();
    if expr.is_empty() {
        return None;
    }
    if let Some(value) = text_decoration_thickness_value_from_raw(expr) {
        return Some(value);
    }
    if let Some(spec) =
        resolve_custom_length_from_maps(&style.custom_lengths, &style.custom_color_refs, expr)
    {
        return Some(TextDecorationThicknessMode::Length(spec));
    }
    if let Some((name, fallback)) = parse_var_function(expr) {
        if let Some(value) = resolve_text_decoration_thickness_expr_inner(style, &name, depth + 1) {
            return Some(value);
        }
        if let Some(fallback_expr) = fallback {
            return resolve_text_decoration_thickness_expr_inner(style, &fallback_expr, depth + 1);
        }
        return None;
    }
    if expr.starts_with("--") {
        let key = expr.to_ascii_lowercase();
        if let Some(raw) = style.custom_raw_values.get(&key) {
            return resolve_text_decoration_thickness_expr_inner(style, raw, depth + 1);
        }
        if let Some(raw) = style.custom_color_refs.get(&key) {
            return resolve_text_decoration_thickness_expr_inner(style, raw, depth + 1);
        }
    }
    None
}

