const TEXT_WRAP_SHORTHAND_VAR_PREFIX: &str = "__fullbleed_text_wrap_shorthand__:";
const WHITE_SPACE_SHORTHAND_VAR_PREFIX: &str = "__fullbleed_white_space_shorthand__:";

fn text_wrap_shorthand_var_expr(expr: &str) -> String {
    format!("{TEXT_WRAP_SHORTHAND_VAR_PREFIX}{}", expr.trim())
}

fn strip_text_wrap_shorthand_marker(expr: &str) -> Option<&str> {
    expr.strip_prefix(TEXT_WRAP_SHORTHAND_VAR_PREFIX)
}

fn white_space_shorthand_var_expr(expr: &str) -> String {
    format!("{WHITE_SPACE_SHORTHAND_VAR_PREFIX}{}", expr.trim())
}

fn strip_white_space_shorthand_marker(expr: &str) -> Option<&str> {
    expr.strip_prefix(WHITE_SPACE_SHORTHAND_VAR_PREFIX)
}

