fn resolve_vertical_align_expr_inner(
    style: &ComputedStyle,
    expr: &str,
    depth: usize,
) -> Option<VerticalAlignMode> {
    if depth > 12 {
        return None;
    }
    let expr = expr.trim();
    if expr.is_empty() {
        return None;
    }
    if expr.eq_ignore_ascii_case("inherit") {
        return Some(style.vertical_align_inherit_base);
    }
    if let Some(value) = parse_vertical_align_mode_str(expr) {
        return Some(value);
    }
    if let Some((name, fallback)) = parse_var_function(expr) {
        if let Some(value) = resolve_vertical_align_expr_inner(style, &name, depth + 1) {
            return Some(value);
        }
        if let Some(fallback_expr) = fallback {
            return resolve_vertical_align_expr_inner(style, &fallback_expr, depth + 1);
        }
        return None;
    }
    if expr.starts_with("--") {
        let key = expr.to_ascii_lowercase();
        if let Some(raw) = style.custom_raw_values.get(&key) {
            return resolve_vertical_align_expr_inner(style, raw, depth + 1);
        }
        if let Some(raw) = style.custom_color_refs.get(&key) {
            return resolve_vertical_align_expr_inner(style, raw, depth + 1);
        }
    }
    None
}

fn resolve_font_shorthand_expr(
    style: &ComputedStyle,
    expr: &str,
) -> Option<(
    FontStyleMode,
    FontWeightSpec,
    FontSizeSpec,
    LineHeightSpec,
    FontSpec,
)> {
    let mut stack = Vec::new();
    resolve_font_shorthand_expr_inner(style, expr, 0, &mut stack)
}

fn resolve_font_shorthand_expr_inner(
    style: &ComputedStyle,
    expr: &str,
    depth: usize,
    stack: &mut Vec<String>,
) -> Option<(
    FontStyleMode,
    FontWeightSpec,
    FontSizeSpec,
    LineHeightSpec,
    FontSpec,
)> {
    if depth > 16 {
        return None;
    }
    let expr = expr.trim();
    if expr.is_empty() {
        return None;
    }
    if let Some(value) = parse_font_shorthand_raw(expr) {
        return Some(value);
    }
    if let Some((name, fallback)) = parse_var_function(expr) {
        if let Some(value) = resolve_font_shorthand_expr_inner(style, &name, depth + 1, stack) {
            return Some(value);
        }
        if let Some(fallback_expr) = fallback {
            return resolve_font_shorthand_expr_inner(style, &fallback_expr, depth + 1, stack);
        }
        return None;
    }
    if expr.starts_with("--") {
        let key = expr.to_ascii_lowercase();
        if stack.iter().any(|entry| entry == &key) {
            return None;
        }
        stack.push(key.clone());
        let resolved = if let Some(raw) = style.custom_raw_values.get(&key) {
            resolve_font_shorthand_expr_inner(style, raw, depth + 1, stack)
        } else if let Some(next) = style.custom_color_refs.get(&key) {
            resolve_font_shorthand_expr_inner(style, next, depth + 1, stack)
        } else {
            None
        };
        stack.pop();
        return resolved;
    }
    None
}

