fn text_decoration_thickness_value_from_raw(raw: &str) -> Option<TextDecorationThicknessMode> {
    let lowered = raw.trim().to_ascii_lowercase();
    match lowered.as_str() {
        "auto" => return Some(TextDecorationThicknessMode::Auto),
        "from-font" => return Some(TextDecorationThicknessMode::FromFont),
        "hairline" => {
            return Some(TextDecorationThicknessMode::Length(LengthSpec::Absolute(
                Pt::from_f32(0.5),
            )));
        }
        "thin" => {
            return Some(TextDecorationThicknessMode::Length(LengthSpec::Absolute(
                Pt::from_f32(0.75),
            )));
        }
        "medium" => {
            return Some(TextDecorationThicknessMode::Length(LengthSpec::Absolute(
                Pt::from_f32(2.25),
            )));
        }
        "thick" => {
            return Some(TextDecorationThicknessMode::Length(LengthSpec::Absolute(
                Pt::from_f32(3.75),
            )));
        }
        _ => {}
    }
    let spec = length_spec_from_string(&lowered)?;
    match spec {
        LengthSpec::Absolute(value) if value >= Pt::ZERO => Some(
            TextDecorationThicknessMode::Length(LengthSpec::Absolute(value)),
        ),
        LengthSpec::Percent(value) if value >= 0.0 => Some(TextDecorationThicknessMode::Length(
            LengthSpec::Percent(value),
        )),
        LengthSpec::Em(value) if value >= 0.0 => {
            Some(TextDecorationThicknessMode::Length(LengthSpec::Em(value)))
        }
        LengthSpec::Rem(value) if value >= 0.0 => {
            Some(TextDecorationThicknessMode::Length(LengthSpec::Rem(value)))
        }
        LengthSpec::Calc(calc) => Some(TextDecorationThicknessMode::Length(LengthSpec::Calc(calc))),
        _ => None,
    }
}

