fn text_underline_position_value_from_raw(raw: &str) -> Option<TextUnderlinePositionMode> {
    let lowered = raw.trim().to_ascii_lowercase();
    if lowered == "auto" {
        return Some(TextUnderlinePositionMode::auto());
    }
    let mut line = TextUnderlinePositionLine::Auto;
    let mut side = None;
    let parts = split_top_level_whitespace(&lowered);
    if parts.is_empty() || parts.iter().any(|part| part == "auto") {
        return None;
    }
    for part in parts {
        match part.as_str() {
            "from-font" if line == TextUnderlinePositionLine::Auto => {
                line = TextUnderlinePositionLine::FromFont;
            }
            "under" if line == TextUnderlinePositionLine::Auto => {
                line = TextUnderlinePositionLine::Under;
            }
            "left" if side.is_none() => {
                side = Some(TextUnderlinePositionSide::Left);
            }
            "right" if side.is_none() => {
                side = Some(TextUnderlinePositionSide::Right);
            }
            _ => return None,
        }
    }
    Some(TextUnderlinePositionMode { line, side })
}

