fn writing_mode_from_ident(value: &str) -> Option<WritingModeMode> {
    match value.trim().to_ascii_lowercase().as_str() {
        "horizontal-tb" | "lr" | "lr-tb" | "rl" => Some(WritingModeMode::HorizontalTb),
        "vertical-rl" | "tb-rl" => Some(WritingModeMode::VerticalRl),
        "vertical-lr" | "tb" | "tb-lr" => Some(WritingModeMode::VerticalLr),
        "sideways-rl" => Some(WritingModeMode::SidewaysRl),
        "sideways-lr" => Some(WritingModeMode::SidewaysLr),
        _ => None,
    }
}

fn apply_writing_mode_from_str(raw: &str, delta: &mut StyleDelta) {
    match raw.trim().to_ascii_lowercase().as_str() {
        "inherit" => set_delta_writing_mode(delta, WritingModeSpec::Inherit),
        "initial" | "unset" | "revert" => set_delta_writing_mode(delta, WritingModeSpec::Initial),
        "revert-layer" => {
            set_revert_layer_writing_mode(delta);
        }
        value => {
            if let Some(mode) = writing_mode_from_ident(value) {
                set_delta_writing_mode(delta, WritingModeSpec::Value(mode));
            }
        }
    }
}

