fn parse_display_mode_str(raw: &str) -> Option<DisplayMode> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "flow-root" | "block flow-root" | "flow-root block" => Some(DisplayMode::FlowRoot),
        "block"
        | "ruby"
        | "block ruby"
        | "ruby block"
        | "ruby-base"
        | "ruby-text"
        | "ruby-base-container"
        | "ruby-text-container"
        | "-webkit-box"
        | "-moz-box"
        | "block -webkit-box"
        | "block -moz-box" => Some(DisplayMode::Block),
        "inline" | "inline ruby" | "ruby inline" | "-webkit-inline-box" | "-moz-inline-box"
        | "inline -webkit-box" | "inline -moz-box" => Some(DisplayMode::Inline),
        "inline-block" => Some(DisplayMode::InlineBlock),
        "list-item" | "block list-item" | "list-item block" | "flow list-item"
        | "list-item flow" => Some(DisplayMode::ListItem),
        "inline list-item" | "list-item inline" => Some(DisplayMode::InlineListItem),
        "table" => Some(DisplayMode::Table),
        "inline-table" => Some(DisplayMode::InlineTable),
        "table-row-group" => Some(DisplayMode::TableRowGroup),
        "table-header-group" => Some(DisplayMode::TableHeaderGroup),
        "table-footer-group" => Some(DisplayMode::TableFooterGroup),
        "table-row" => Some(DisplayMode::TableRow),
        "table-cell" => Some(DisplayMode::TableCell),
        "table-column-group" => Some(DisplayMode::TableColumnGroup),
        "table-column" => Some(DisplayMode::TableColumn),
        "table-caption" => Some(DisplayMode::TableCaption),
        "flex" | "block flex" | "flex block" => Some(DisplayMode::Flex),
        "inline-flex" | "inline flex" | "flex inline" => Some(DisplayMode::InlineFlex),
        "grid" | "block grid" | "grid block" => Some(DisplayMode::Grid),
        "inline-grid" | "inline grid" | "grid inline" => Some(DisplayMode::InlineGrid),
        "none" => Some(DisplayMode::None),
        "contents" => Some(DisplayMode::Contents),
        _ => None,
    }
}

fn parse_display_spec_str(raw: &str) -> Option<DisplaySpec> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "inherit" => Some(DisplaySpec::Inherit),
        "initial" | "unset" | "revert" => Some(DisplaySpec::Initial),
        "revert-layer" => None,
        value => parse_display_mode_str(value).map(DisplaySpec::Value),
    }
}

