    #[test]
    fn revert_layer_resets_border_style_edges_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { border-width: 4px; border-style: solid; } \
                     .feature { border-style: dotted dashed double groove; } \
                     .logical { writing-mode: vertical-rl; direction: ltr; border-inline-start-style: dotted; border-inline-end-style: dashed; border-block-start-style: double; border-block-end-style: groove; } \
                     .override { border-style: inset outset ridge groove; } \
                   } \
                   @layer special { \
                     .item { border-style: dashed dotted solid double; } \
                     .feature { border-style: revert-layer; } \
                     .logical { border-inline-start-style: revert-layer; border-inline-end-style: revert-layer; border-block-start-style: revert-layer; border-block-end-style: revert-layer; } \
                     .override { border-style: revert-layer; border-left-style: solid; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let physical =
            resolver.compute_style(&element("p", None, &["item", "feature"]), &root, None, &[]);
        assert_eq!(
            physical.border_style.top,
            BorderLineStyle::Style(OutlineLineStyle::Dotted)
        );
        assert_eq!(
            physical.border_style.right,
            BorderLineStyle::Style(OutlineLineStyle::Dashed)
        );
        assert_eq!(
            physical.border_style.bottom,
            BorderLineStyle::Style(OutlineLineStyle::Double)
        );
        assert_eq!(
            physical.border_style.left,
            BorderLineStyle::Style(OutlineLineStyle::Groove)
        );

        let logical =
            resolver.compute_style(&element("p", None, &["item", "logical"]), &root, None, &[]);
        assert_eq!(
            logical.border_style.top,
            BorderLineStyle::Style(OutlineLineStyle::Dotted)
        );
        assert_eq!(
            logical.border_style.right,
            BorderLineStyle::Style(OutlineLineStyle::Double)
        );
        assert_eq!(
            logical.border_style.bottom,
            BorderLineStyle::Style(OutlineLineStyle::Dashed)
        );
        assert_eq!(
            logical.border_style.left,
            BorderLineStyle::Style(OutlineLineStyle::Groove)
        );

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(
            current_layer.border_style.top,
            BorderLineStyle::Style(OutlineLineStyle::Dashed)
        );
        assert_eq!(
            current_layer.border_style.right,
            BorderLineStyle::Style(OutlineLineStyle::Dotted)
        );
        assert_eq!(
            current_layer.border_style.bottom,
            BorderLineStyle::Style(OutlineLineStyle::Solid)
        );
        assert_eq!(
            current_layer.border_style.left,
            BorderLineStyle::Style(OutlineLineStyle::Double)
        );

        let later_edge =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(
            later_edge.border_style.top,
            BorderLineStyle::Style(OutlineLineStyle::Inset)
        );
        assert_eq!(
            later_edge.border_style.right,
            BorderLineStyle::Style(OutlineLineStyle::Outset)
        );
        assert_eq!(
            later_edge.border_style.bottom,
            BorderLineStyle::Style(OutlineLineStyle::Ridge)
        );
        assert_eq!(
            later_edge.border_style.left,
            BorderLineStyle::Style(OutlineLineStyle::Solid)
        );
    }

    #[test]
    fn revert_layer_resets_border_color_edges_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { color: rgb(9, 19, 29); border-style: solid; border-width: 4px; border-color: rgb(1, 2, 3); } \
                     .feature { border-color: rgb(20, 40, 60) rgb(70, 80, 90) rgb(100, 110, 120) rgb(130, 140, 150); } \
                     .logical { writing-mode: vertical-rl; direction: ltr; border-inline-start-color: rgb(20, 40, 60); border-inline-end-color: rgb(70, 80, 90); border-block-start-color: rgb(100, 110, 120); border-block-end-color: rgb(130, 140, 150); } \
                     .override { border-color: rgb(10, 20, 30) rgb(40, 50, 60) rgb(70, 80, 90) rgb(100, 110, 120); } \
                   } \
                   @layer special { \
                     .item { border-color: rgb(200, 0, 0) rgb(0, 200, 0) rgb(0, 0, 200) rgb(200, 200, 0); } \
                     .feature { border-color: revert-layer; } \
                     .logical { border-inline-start-color: revert-layer; border-inline-end-color: revert-layer; border-block-start-color: revert-layer; border-block-end-color: revert-layer; } \
                     .override { border-color: revert-layer; border-left-color: rgb(9, 8, 7); } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let physical =
            resolver.compute_style(&element("p", None, &["item", "feature"]), &root, None, &[]);
        assert_eq!(physical.border_top_color, Some(rgb8(20, 40, 60)));
        assert_eq!(physical.border_right_color, Some(rgb8(70, 80, 90)));
        assert_eq!(physical.border_bottom_color, Some(rgb8(100, 110, 120)));
        assert_eq!(physical.border_left_color, Some(rgb8(130, 140, 150)));

        let logical =
            resolver.compute_style(&element("p", None, &["item", "logical"]), &root, None, &[]);
        assert_eq!(logical.border_top_color, Some(rgb8(20, 40, 60)));
        assert_eq!(logical.border_right_color, Some(rgb8(100, 110, 120)));
        assert_eq!(logical.border_bottom_color, Some(rgb8(70, 80, 90)));
        assert_eq!(logical.border_left_color, Some(rgb8(130, 140, 150)));

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.border_top_color, Some(rgb8(200, 0, 0)));
        assert_eq!(current_layer.border_right_color, Some(rgb8(0, 200, 0)));
        assert_eq!(current_layer.border_bottom_color, Some(rgb8(0, 0, 200)));
        assert_eq!(current_layer.border_left_color, Some(rgb8(200, 200, 0)));

        let later_edge =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_edge.border_top_color, Some(rgb8(10, 20, 30)));
        assert_eq!(later_edge.border_right_color, Some(rgb8(40, 50, 60)));
        assert_eq!(later_edge.border_bottom_color, Some(rgb8(70, 80, 90)));
        assert_eq!(later_edge.border_left_color, Some(rgb8(9, 8, 7)));
    }

    #[test]
    fn revert_layer_resets_outline_shorthand_and_longhands_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { outline: 4px solid rgb(10, 20, 30); } \
                     .feature { outline: 6px dashed rgb(40, 50, 60); } \
                     .parts { outline-width: 8px; outline-style: dotted; outline-color: rgb(70, 80, 90); } \
                     .override { outline: 10px groove rgb(100, 110, 120); } \
                   } \
                   @layer special { \
                     .item { outline: 1px double rgb(200, 0, 0); } \
                     .feature { outline: revert-layer; } \
                     .parts { outline-width: revert-layer; outline-style: revert-layer; outline-color: revert-layer; } \
                     .override { outline-width: revert-layer; outline-style: revert-layer; outline-color: revert-layer; outline-color: rgb(9, 8, 7); } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let shorthand =
            resolver.compute_style(&element("p", None, &["item", "feature"]), &root, None, &[]);
        assert_eq!(shorthand.outline_width, LengthSpec::Absolute(px_to_pt(6.0)));
        assert_eq!(shorthand.outline_style, OutlineLineStyle::Dashed);
        assert_eq!(shorthand.resolved_outline_color(), rgb8(40, 50, 60));
        assert!(shorthand.outline_visible);

        let longhands =
            resolver.compute_style(&element("p", None, &["item", "parts"]), &root, None, &[]);
        assert_eq!(longhands.outline_width, LengthSpec::Absolute(px_to_pt(8.0)));
        assert_eq!(longhands.outline_style, OutlineLineStyle::Dotted);
        assert_eq!(longhands.resolved_outline_color(), rgb8(70, 80, 90));
        assert!(longhands.outline_visible);

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(
            current_layer.outline_width,
            LengthSpec::Absolute(px_to_pt(1.0))
        );
        assert_eq!(current_layer.outline_style, OutlineLineStyle::Double);
        assert_eq!(current_layer.resolved_outline_color(), rgb8(200, 0, 0));
        assert!(current_layer.outline_visible);

        let later_color =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(
            later_color.outline_width,
            LengthSpec::Absolute(px_to_pt(10.0))
        );
        assert_eq!(later_color.outline_style, OutlineLineStyle::Groove);
        assert_eq!(later_color.resolved_outline_color(), rgb8(9, 8, 7));
        assert!(later_color.outline_visible);
    }

