    #[test]
    fn revert_layer_resets_text_decoration_metrics_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { text-decoration-line: underline; text-decoration-thickness: 2pt; text-decoration-style: solid; text-underline-offset: 2pt; text-underline-position: auto; } \
                     .revert { text-decoration-line: underline overline; text-decoration-thickness: 7pt; text-decoration-style: dashed; text-underline-offset: 8pt; text-underline-position: under right; } \
                     .override { text-decoration-line: underline overline; text-decoration-thickness: 7pt; text-decoration-style: dashed; text-underline-offset: 8pt; text-underline-position: under right; } \
                   } \
                   @layer special { \
                     .item { text-decoration-line: line-through; text-decoration-thickness: 4pt; text-decoration-style: double; text-underline-offset: -0.25em; text-underline-position: auto; } \
                     .revert { text-decoration-line: revert-layer; text-decoration-thickness: revert-layer; text-decoration-style: revert-layer; text-underline-offset: revert-layer; text-underline-position: revert-layer; } \
                     .override { text-decoration-line: revert-layer; text-decoration-thickness: revert-layer; text-decoration-style: revert-layer; text-underline-offset: revert-layer; text-underline-position: revert-layer; text-decoration-line: underline; text-decoration-thickness: 5pt; text-decoration-style: wavy; text-underline-offset: 10%; text-underline-position: under; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let reverted =
            resolver.compute_style(&element("p", None, &["item", "revert"]), &root, None, &[]);
        assert_eq!(
            reverted.text_decoration,
            TextDecorationMode {
                underline: true,
                overline: true,
                line_through: false,
            }
        );
        assert_eq!(
            reverted.text_decoration_thickness,
            TextDecorationThicknessMode::Length(LengthSpec::Absolute(Pt::from_f32(7.0)))
        );
        assert_eq!(
            reverted.text_decoration_style,
            TextDecorationStyleMode::Dashed
        );
        assert_eq!(
            reverted.text_underline_offset,
            TextUnderlineOffsetMode::Length(LengthSpec::Absolute(Pt::from_f32(8.0)))
        );
        assert_eq!(
            reverted.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Under,
                side: Some(TextUnderlinePositionSide::Right),
            }
        );

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(
            current_layer.text_decoration,
            TextDecorationMode {
                underline: false,
                overline: false,
                line_through: true,
            }
        );
        assert_eq!(
            current_layer.text_decoration_thickness,
            TextDecorationThicknessMode::Length(LengthSpec::Absolute(Pt::from_f32(4.0)))
        );
        assert_eq!(
            current_layer.text_decoration_style,
            TextDecorationStyleMode::Double
        );
        assert_eq!(
            current_layer.text_underline_offset,
            TextUnderlineOffsetMode::Length(LengthSpec::Em(-0.25))
        );
        assert_eq!(
            current_layer.text_underline_position,
            TextUnderlinePositionMode::auto()
        );

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(
            later_declaration.text_decoration,
            TextDecorationMode {
                underline: true,
                overline: false,
                line_through: false,
            }
        );
        assert_eq!(
            later_declaration.text_decoration_thickness,
            TextDecorationThicknessMode::Length(LengthSpec::Absolute(Pt::from_f32(5.0)))
        );
        assert_eq!(
            later_declaration.text_decoration_style,
            TextDecorationStyleMode::Wavy
        );
        assert_eq!(
            later_declaration.text_underline_offset,
            TextUnderlineOffsetMode::Length(LengthSpec::Percent(0.1))
        );
        assert_eq!(
            later_declaration.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Under,
                side: None,
            }
        );
    }

