    #[test]
    fn revert_layer_resets_text_transform_line_break_and_hyphenation_to_previous_layer() {
        let css = r#"@layer base, special;
                   @layer base {
                     .item { text-transform: uppercase; line-break: loose; hyphens: auto; hyphenate-character: "~"; }
                     .revert { text-transform: lowercase; line-break: strict; hyphens: none; hyphenate-character: "="; }
                     .override { text-transform: lowercase; line-break: strict; hyphens: none; hyphenate-character: "="; }
                   }
                   @layer special {
                     .item { text-transform: capitalize; line-break: anywhere; hyphens: manual; hyphenate-character: "_"; }
                     .revert { text-transform: revert-layer; line-break: revert-layer; hyphens: revert-layer; hyphenate-character: revert-layer; }
                     .override { text-transform: revert-layer; line-break: revert-layer; hyphens: revert-layer; hyphenate-character: revert-layer; text-transform: none; line-break: normal; hyphens: auto; hyphenate-character: auto; }
                   }"#;
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let reverted =
            resolver.compute_style(&element("p", None, &["item", "revert"]), &root, None, &[]);
        assert_eq!(reverted.text_transform, TextTransformMode::Lowercase);
        assert_eq!(reverted.line_break, LineBreakMode::Strict);
        assert_eq!(reverted.hyphens, HyphensMode::None);
        assert_eq!(reverted.hyphenate_character.as_deref(), Some("="));

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.text_transform, TextTransformMode::Capitalize);
        assert_eq!(current_layer.line_break, LineBreakMode::Anywhere);
        assert_eq!(current_layer.hyphens, HyphensMode::Manual);
        assert_eq!(current_layer.hyphenate_character.as_deref(), Some("_"));

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_declaration.text_transform, TextTransformMode::None);
        assert_eq!(later_declaration.line_break, LineBreakMode::Normal);
        assert_eq!(later_declaration.hyphens, HyphensMode::Auto);
        assert_eq!(later_declaration.hyphenate_character.as_deref(), None);
    }

    #[test]
    fn revert_layer_resets_word_break_and_overflow_wrap_to_previous_layer() {
        let css = r#"@layer base, special;
                   @layer base {
                     .item { overflow-wrap: normal; word-break: normal; }
                     .word { word-break: break-all; }
                     .overflow { overflow-wrap: break-word; }
                     .alias { word-wrap: break-word; }
                     .override { word-break: keep-all; }
                   }
                   @layer special {
                     .item { overflow-wrap: anywhere; }
                     .word { word-break: revert-layer; }
                     .overflow { overflow-wrap: revert-layer; }
                     .alias { word-wrap: revert-layer; }
                     .override { word-break: revert-layer; word-break: normal; }
                   }"#;
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.word_break, WordBreakMode::Anywhere);

        let word_break_reverted =
            resolver.compute_style(&element("p", None, &["item", "word"]), &root, None, &[]);
        assert_eq!(word_break_reverted.word_break, WordBreakMode::BreakAll);

        let overflow_wrap_reverted =
            resolver.compute_style(&element("p", None, &["item", "overflow"]), &root, None, &[]);
        assert_eq!(overflow_wrap_reverted.word_break, WordBreakMode::BreakWord);

        let word_wrap_alias_reverted =
            resolver.compute_style(&element("p", None, &["item", "alias"]), &root, None, &[]);
        assert_eq!(
            word_wrap_alias_reverted.word_break,
            WordBreakMode::BreakWord
        );

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_declaration.word_break, WordBreakMode::Normal);
    }

    #[test]
    fn revert_layer_resets_white_space_and_text_wrap_to_previous_layer() {
        let css = r#"@layer base, special;
                   @layer base {
                     .item { white-space: normal; text-wrap: wrap; }
                     .white { white-space: preserve nowrap; }
                     .collapse { white-space-collapse: preserve-spaces; }
                     .wrap { text-wrap: nowrap pretty; }
                     .mode { text-wrap-mode: nowrap; }
                     .style { text-wrap-style: stable; }
                     .override { white-space: pre-wrap; text-wrap: nowrap pretty; }
                   }
                   @layer special {
                     .item { white-space: collapse; text-wrap: balance; }
                     .white { white-space: revert-layer; }
                     .collapse { white-space-collapse: revert-layer; }
                     .wrap { text-wrap: revert-layer; }
                     .mode { text-wrap-mode: revert-layer; }
                     .style { text-wrap-style: revert-layer; }
                     .override { white-space: revert-layer; text-wrap: revert-layer; white-space: pre-line; text-wrap: nowrap stable; }
                   }"#;
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.white_space, WhiteSpaceMode::Normal);
        assert_eq!(current_layer.text_wrap_mode, TextWrapMode::Wrap);
        assert_eq!(current_layer.text_wrap_style, TextWrapStyleMode::Balance);

        let white_space_reverted =
            resolver.compute_style(&element("p", None, &["item", "white"]), &root, None, &[]);
        assert_eq!(white_space_reverted.white_space, WhiteSpaceMode::Pre);
        assert_eq!(white_space_reverted.text_wrap_mode, TextWrapMode::NoWrap);
        assert_eq!(
            white_space_reverted.text_wrap_style,
            TextWrapStyleMode::Balance
        );

        let collapse_reverted =
            resolver.compute_style(&element("p", None, &["item", "collapse"]), &root, None, &[]);
        assert_eq!(
            collapse_reverted.white_space,
            WhiteSpaceMode::PreserveSpaces
        );
        assert_eq!(collapse_reverted.text_wrap_mode, TextWrapMode::Wrap);
        assert_eq!(
            collapse_reverted.text_wrap_style,
            TextWrapStyleMode::Balance
        );

        let text_wrap_reverted =
            resolver.compute_style(&element("p", None, &["item", "wrap"]), &root, None, &[]);
        assert_eq!(text_wrap_reverted.white_space, WhiteSpaceMode::Normal);
        assert_eq!(text_wrap_reverted.text_wrap_mode, TextWrapMode::NoWrap);
        assert_eq!(
            text_wrap_reverted.text_wrap_style,
            TextWrapStyleMode::Pretty
        );

        let mode_reverted =
            resolver.compute_style(&element("p", None, &["item", "mode"]), &root, None, &[]);
        assert_eq!(mode_reverted.text_wrap_mode, TextWrapMode::NoWrap);
        assert_eq!(mode_reverted.text_wrap_style, TextWrapStyleMode::Balance);

        let style_reverted =
            resolver.compute_style(&element("p", None, &["item", "style"]), &root, None, &[]);
        assert_eq!(style_reverted.text_wrap_mode, TextWrapMode::Wrap);
        assert_eq!(style_reverted.text_wrap_style, TextWrapStyleMode::Stable);

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_declaration.white_space, WhiteSpaceMode::PreLine);
        assert_eq!(later_declaration.text_wrap_mode, TextWrapMode::NoWrap);
        assert_eq!(later_declaration.text_wrap_style, TextWrapStyleMode::Stable);
    }

