    #[test]
    fn revert_layer_resets_direction_and_writing_mode_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { position: absolute; width: 10px; height: 10px; direction: ltr; writing-mode: horizontal-tb; } \
                     .dir { direction: rtl; } \
                     .mode { writing-mode: vertical-rl; } \
                     .both { direction: rtl; writing-mode: vertical-rl; inset-inline-start: 8px; inset-block-start: 12px; } \
                     .override { direction: rtl; writing-mode: vertical-rl; } \
                   } \
                   @layer special { \
                     .item { direction: ltr; writing-mode: horizontal-tb; } \
                     .dir { direction: revert-layer; } \
                     .mode { writing-mode: revert-layer; } \
                     .both { direction: revert-layer; writing-mode: revert-layer; } \
                     .override { direction: revert-layer; writing-mode: revert-layer; direction: ltr; writing-mode: vertical-lr; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.direction, DirectionMode::Ltr);
        assert_eq!(current_layer.writing_mode, WritingModeMode::HorizontalTb);

        let direction_reverted =
            resolver.compute_style(&element("p", None, &["item", "dir"]), &root, None, &[]);
        assert_eq!(direction_reverted.direction, DirectionMode::Rtl);
        assert_eq!(
            direction_reverted.writing_mode,
            WritingModeMode::HorizontalTb
        );

        let writing_mode_reverted =
            resolver.compute_style(&element("p", None, &["item", "mode"]), &root, None, &[]);
        assert_eq!(writing_mode_reverted.direction, DirectionMode::Ltr);
        assert_eq!(
            writing_mode_reverted.writing_mode,
            WritingModeMode::VerticalRl
        );

        let both_reverted =
            resolver.compute_style(&element("p", None, &["item", "both"]), &root, None, &[]);
        assert_eq!(both_reverted.direction, DirectionMode::Rtl);
        assert_eq!(both_reverted.writing_mode, WritingModeMode::VerticalRl);
        assert_eq!(
            both_reverted.inset_bottom,
            LengthSpec::Absolute(px_to_pt(8.0))
        );
        assert_eq!(
            both_reverted.inset_right,
            LengthSpec::Absolute(px_to_pt(12.0))
        );

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_declaration.direction, DirectionMode::Ltr);
        assert_eq!(later_declaration.writing_mode, WritingModeMode::VerticalLr);
    }

    #[test]
    fn revert_layer_resets_overflow_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { overflow: visible; } \
                     .revert { overflow: hidden visible; } \
                     .inline { writing-mode: vertical-rl; overflow-inline: hidden; overflow-block: visible; } \
                     .override { overflow: hidden; } \
                   } \
                   @layer special { \
                     .item { overflow: hidden; } \
                     .revert { overflow: revert-layer; } \
                     .inline { overflow-inline: revert-layer; overflow-block: revert-layer; } \
                     .override { overflow: revert-layer; overflow: visible; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let reverted =
            resolver.compute_style(&element("p", None, &["item", "revert"]), &root, None, &[]);
        assert_eq!(reverted.overflow_x, OverflowMode::Hidden);
        assert_eq!(reverted.overflow_y, OverflowMode::Visible);
        assert_eq!(reverted.overflow, OverflowMode::Hidden);

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert_eq!(current_layer.overflow_x, OverflowMode::Hidden);
        assert_eq!(current_layer.overflow_y, OverflowMode::Hidden);
        assert_eq!(current_layer.overflow, OverflowMode::Hidden);

        let logical =
            resolver.compute_style(&element("p", None, &["item", "inline"]), &root, None, &[]);
        assert_eq!(logical.overflow_x, OverflowMode::Visible);
        assert_eq!(logical.overflow_y, OverflowMode::Hidden);
        assert_eq!(logical.overflow, OverflowMode::Hidden);

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert_eq!(later_declaration.overflow_x, OverflowMode::Visible);
        assert_eq!(later_declaration.overflow_y, OverflowMode::Visible);
        assert_eq!(later_declaration.overflow, OverflowMode::Visible);
    }

