    #[test]
    fn revert_layer_resets_isolation_to_previous_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .item { isolation: auto; } \
                     .revert { isolation: auto; } \
                     .override { isolation: isolate; } \
                   } \
                   @layer special { \
                     .item { isolation: isolate; } \
                     .revert { isolation: revert-layer; } \
                     .override { isolation: revert-layer; isolation: auto; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let reverted =
            resolver.compute_style(&element("p", None, &["item", "revert"]), &root, None, &[]);
        assert!(!reverted.isolation);

        let current_layer =
            resolver.compute_style(&element("p", None, &["item"]), &root, None, &[]);
        assert!(current_layer.isolation);

        let later_declaration =
            resolver.compute_style(&element("p", None, &["item", "override"]), &root, None, &[]);
        assert!(!later_declaration.isolation);
    }

    #[test]
    fn supports_rule_conditions_gate_nested_rules() {
        let css = ".item { color: rgb(0, 0, 0); } \
                   @supports (display: flex) { .supported { color: rgb(255, 0, 0); } } \
                   @supports not (display: no-such-value) { .not-supported { color: rgb(0, 128, 0); } } \
                   @supports (display: flex) and (color: rgb(0, 0, 0)) { .and-supported { color: rgb(0, 0, 255); } } \
                   @supports (display: no-such-value) or (display: block) { .or-supported { color: rgb(128, 0, 128); } } \
                   @supports selector(.selector-supported) { .selector-supported { color: rgb(255, 128, 0); } } \
                   @supports (display: no-such-value) { .unsupported { color: rgb(255, 0, 0); } }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let supported = resolver.compute_style(
            &element("p", None, &["item", "supported"]),
            &root,
            None,
            &[],
        );
        let not_supported = resolver.compute_style(
            &element("p", None, &["item", "not-supported"]),
            &root,
            None,
            &[],
        );
        let and_supported = resolver.compute_style(
            &element("p", None, &["item", "and-supported"]),
            &root,
            None,
            &[],
        );
        let or_supported = resolver.compute_style(
            &element("p", None, &["item", "or-supported"]),
            &root,
            None,
            &[],
        );
        let selector_supported = resolver.compute_style(
            &element("p", None, &["item", "selector-supported"]),
            &root,
            None,
            &[],
        );
        let unsupported = resolver.compute_style(
            &element("p", None, &["item", "unsupported"]),
            &root,
            None,
            &[],
        );

        assert_eq!(supported.color, Color::rgb(1.0, 0.0, 0.0));
        assert_eq!(not_supported.color, Color::rgb(0.0, 128.0 / 255.0, 0.0));
        assert_eq!(and_supported.color, Color::rgb(0.0, 0.0, 1.0));
        assert_eq!(
            or_supported.color,
            Color::rgb(128.0 / 255.0, 0.0, 128.0 / 255.0)
        );
        assert_eq!(
            selector_supported.color,
            Color::rgb(1.0, 128.0 / 255.0, 0.0)
        );
        assert_eq!(unsupported.color, Color::rgb(0.0, 0.0, 0.0));
    }

