    #[test]
    fn media_print_type_takes_precedence_for_paged_output() {
        let css = ".print, .screen, .all, .not-print, .listed { color: rgb(0, 0, 0); } \
                   @media print { .print { color: rgb(0, 128, 0); } } \
                   @media screen { .screen { color: rgb(255, 0, 0); } } \
                   @media all { .all { color: rgb(0, 0, 255); } } \
                   @media not print { .not-print { color: rgb(255, 128, 0); } } \
                   @media screen, print { .listed { color: rgb(128, 0, 128); } }";
        let viewport = Size {
            width: Pt::from_f32(600.0),
            height: Pt::from_f32(400.0),
        };
        let resolver = StyleResolver::new_with_debug_and_viewport(css, None, Some(viewport));
        let root = resolver.default_style();

        let print = resolver.compute_style(&element("p", None, &["print"]), &root, None, &[]);
        let screen = resolver.compute_style(&element("p", None, &["screen"]), &root, None, &[]);
        let all = resolver.compute_style(&element("p", None, &["all"]), &root, None, &[]);
        let not_print =
            resolver.compute_style(&element("p", None, &["not-print"]), &root, None, &[]);
        let listed = resolver.compute_style(&element("p", None, &["listed"]), &root, None, &[]);

        assert_eq!(print.color, Color::rgb(0.0, 128.0 / 255.0, 0.0));
        assert_eq!(screen.color, Color::rgb(0.0, 0.0, 0.0));
        assert_eq!(all.color, Color::rgb(0.0, 0.0, 1.0));
        assert_eq!(not_print.color, Color::rgb(0.0, 0.0, 0.0));
        assert_eq!(listed.color, Color::rgb(128.0 / 255.0, 0.0, 128.0 / 255.0));
    }

