        let moz_high = resolver.compute_style(&element("p", None, &["moz-high"]), &root, None, &[]);
        let moz_bool = resolver.compute_style(&element("p", None, &["moz-bool"]), &root, None, &[]);

        assert_eq!(webkit_one.color, Color::rgb(0.0, 128.0 / 255.0, 0.0));
