    #[test]
    fn overflow_clip_keeps_its_non_bfc_clipping_mode() {
        let cases = [
            ("visible", OverflowMode::Visible),
            ("hidden", OverflowMode::Hidden),
            ("clip", OverflowMode::Clip),
            ("scroll", OverflowMode::Hidden),
            ("auto", OverflowMode::Hidden),
        ];
        for (keyword, expected) in cases {
            let css = format!(".x {{ overflow: {keyword}; }}");
            let resolver = StyleResolver::new(&css);
            let root = resolver.default_style();
            let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
            assert_eq!(style.overflow, expected, "keyword={keyword}");
        }

        let resolver = StyleResolver::new(".x { overflow-x: hidden; overflow-y: visible; }");
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        assert_eq!(style.overflow, OverflowMode::Hidden);

        let resolver = StyleResolver::new(
            ".x { overflow-x: hidden; overflow-y: visible; overflow-x: visible; }",
        );
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        assert_eq!(style.overflow, OverflowMode::Visible);

        let resolver =
            StyleResolver::new(".x { overflow-inline: hidden; overflow-block: visible; }");
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        assert_eq!(style.overflow, OverflowMode::Hidden);

        let resolver = StyleResolver::new(
            ".x { writing-mode: vertical-rl; overflow-inline: visible; overflow-block: clip; }",
        );
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        assert_eq!(style.overflow, OverflowMode::Clip);
    }

    #[test]
    fn visibility_parses_inherits_and_reverts_layer() {
        let css = "@layer base, special; \
                   @layer base { \
                     .parent { visibility: hidden; } \
                     .child { visibility: visible; } \
                     .collapse { visibility: collapse; } \
                     .revert { visibility: hidden; } \
                   } \
                   @layer special { \
                     .revert { visibility: visible; } \
                     .revert.layer { visibility: revert-layer; } \
                     .override { visibility: hidden; visibility: visible; } \
                   }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let parent = resolver.compute_style(&element("div", None, &["parent"]), &root, None, &[]);
        assert_eq!(parent.visibility, VisibilityMode::Hidden);

        let inherited =
            resolver.compute_style(&element("div", None, &["plain"]), &parent, None, &[]);
        assert_eq!(inherited.visibility, VisibilityMode::Hidden);

        let child = resolver.compute_style(&element("div", None, &["child"]), &parent, None, &[]);
        assert_eq!(child.visibility, VisibilityMode::Visible);

        let collapse =
            resolver.compute_style(&element("div", None, &["collapse"]), &root, None, &[]);
        assert_eq!(collapse.visibility, VisibilityMode::Collapse);

        let reverted = resolver.compute_style(
            &element("div", None, &["revert", "layer"]),
            &root,
            None,
            &[],
        );
        assert_eq!(reverted.visibility, VisibilityMode::Hidden);

        let override_style =
            resolver.compute_style(&element("div", None, &["override"]), &root, None, &[]);
        assert_eq!(override_style.visibility, VisibilityMode::Visible);
    }

