    #[test]
    fn mix_blend_mode_standard_keywords_resolve() {
        let cases = [
            ("normal", MixBlendMode::Normal),
            ("multiply", MixBlendMode::Multiply),
            ("screen", MixBlendMode::Screen),
            ("overlay", MixBlendMode::Overlay),
            ("darken", MixBlendMode::Darken),
            ("lighten", MixBlendMode::Lighten),
            ("color-dodge", MixBlendMode::ColorDodge),
            ("color-burn", MixBlendMode::ColorBurn),
            ("hard-light", MixBlendMode::HardLight),
            ("soft-light", MixBlendMode::SoftLight),
            ("difference", MixBlendMode::Difference),
            ("exclusion", MixBlendMode::Exclusion),
            ("hue", MixBlendMode::Hue),
            ("saturation", MixBlendMode::Saturation),
            ("color", MixBlendMode::Color),
            ("luminosity", MixBlendMode::Luminosity),
            ("plus-lighter", MixBlendMode::PlusLighter),
            ("plus-darker", MixBlendMode::PlusDarker),
        ];
        for (keyword, expected) in cases {
            let css = format!(".x {{ mix-blend-mode: {}; }}", keyword);
            let resolver = StyleResolver::new(&css);
            let root = resolver.default_style();
            let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
            assert_eq!(style.mix_blend_mode, expected, "keyword={keyword}");
        }
    }

    #[test]
    fn isolation_property_resolves_and_is_not_inherited_by_default() {
        let css = ".parent { isolation: isolate; } .child { isolation: auto; }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let parent = resolver.compute_style(&element("div", None, &["parent"]), &root, None, &[]);
        let child = resolver.compute_style(
            &element("div", None, &["child"]),
            &parent,
            None,
            &[element("div", None, &["parent"])],
        );
        assert!(parent.isolation);
        assert!(!child.isolation);
    }

    #[test]
    fn opacity_property_resolves_percentage_and_is_not_inherited_by_default() {
        let css = ".parent { opacity: 25%; } .child { opacity: initial; }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let parent = resolver.compute_style(&element("div", None, &["parent"]), &root, None, &[]);
        let child = resolver.compute_style(
            &element("div", None, &["child"]),
            &parent,
            None,
            &[element("div", None, &["parent"])],
        );
        assert!((parent.opacity - 0.25).abs() < 0.0001);
        assert!((child.opacity - 1.0).abs() < 0.0001);
    }

    #[test]
    fn opacity_var_reparses_percentage_after_substitution() {
        let css = ":root { --half-opacity: 50%; } .target { opacity: var(--half-opacity); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let mut root_info = element("html", None, &[]);
        root_info.is_root = true;
        let root_style = resolver.compute_style(&root_info, &root, None, &[]);
        let target = resolver.compute_style(
            &element("div", None, &["target"]),
            &root_style,
            None,
            &[root_info],
        );

        assert!((target.opacity - 0.5).abs() < 0.0001);
    }

    #[test]
    fn translucent_background_retains_source_color_and_alpha_for_paint() {
        let resolver = StyleResolver::new(".x { background: rgba(255, 87, 34, 0.5); }");
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        let source = style
            .background_source_color
            .expect("translucent source color");

        assert!((source.r - 1.0).abs() < 0.001);
        assert!((source.g - (87.0 / 255.0)).abs() < 0.001);
        assert!((source.b - (34.0 / 255.0)).abs() < 0.001);
        assert!((style.background_alpha - 0.5).abs() < 0.001);
    }

    #[test]
    fn debug_does_not_log_filters_effects_fallback_for_supported_filter_and_mix_blend_mode() {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        let path = std::env::temp_dir().join(format!(
            "fullbleed_style_effects_supported_filter_mix_{}_{}.jsonl",
            std::process::id(),
            nanos
        ));
        let logger = Arc::new(DebugLogger::new(&path).expect("debug logger"));
        let resolver = StyleResolver::new_with_debug(
            ".x { font-size: 24px; filter: blur(0.5em) drop-shadow(blue 1em 0 0.25em) drop-shadow(-2px 1px 0 red) saturate(1.2) grayscale(20%) brightness(120%) contrast(90%) invert(10%) sepia(15%) hue-rotate(90deg) opacity(85%); mix-blend-mode: plus-lighter; }",
            Some(logger.clone()),
        );
        drop(resolver);
        drop(logger);
        let log = std::fs::read_to_string(&path).expect("read debug log");
        assert!(
            !log.contains("\"FILTERS_EFFECTS_FALLBACK\",\"property\":\"filter\""),
            "supported filter should not emit fallback, log={log}"
        );
        assert!(
            !log.contains("\"FILTERS_EFFECTS_FALLBACK\",\"property\":\"mix-blend-mode\""),
            "supported mix-blend-mode should not emit fallback, log={log}"
        );
        let _ = std::fs::remove_file(path);
    }

