    #[test]
    fn clip_path_shape_function_relative_control_points_resolve_on_computed_style() {
        let css = ".x { clip-path: shape(from 0% 100%, curve to 100% 100% with 35% 0% from origin / -35% -100% from end, smooth to 0% 100% with 35% 0% from origin, close); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let style = resolver.compute_style(&element("div", None, &["x"]), &root, None, &[]);
        let spec = match style.clip_path {
            Some(ClipPathShapeSpec::ShapeFunction(spec)) => spec,
            other => panic!("expected shape() clip-path, got {other:?}"),
        };
        assert_eq!(spec.commands.len(), 3);
        match spec.commands[0] {
            ClipPathShapeFunctionCommand::CurveTo {
                control1_x,
                control1_y,
                control1_anchor,
                control2_x,
                control2_y,
                control2_anchor,
                ..
            } => {
                assert_eq!(control1_x, LengthSpec::Percent(0.35));
                assert_eq!(control1_y, LengthSpec::Percent(0.0));
                assert_eq!(control1_anchor, ClipPathShapeControlAnchor::Origin);
                assert_eq!(control2_x, Some(LengthSpec::Percent(-0.35)));
                assert_eq!(control2_y, Some(LengthSpec::Percent(-1.0)));
                assert_eq!(control2_anchor, Some(ClipPathShapeControlAnchor::End));
            }
            other => panic!("expected curve command, got {other:?}"),
        }
        match spec.commands[1] {
            ClipPathShapeFunctionCommand::SmoothTo {
                control_x,
                control_y,
                control_anchor,
                ..
            } => {
                assert_eq!(control_x, Some(LengthSpec::Percent(0.35)));
                assert_eq!(control_y, Some(LengthSpec::Percent(0.0)));
                assert_eq!(control_anchor, Some(ClipPathShapeControlAnchor::Origin));
            }
            other => panic!("expected smooth command, got {other:?}"),
        }
        assert_eq!(spec.commands[2], ClipPathShapeFunctionCommand::Close);
    }

