    #[test]
    fn object_position_inherits_and_resolves_position_grammar() {
        let resolver = StyleResolver::new(
            "body { object-position: right top; } .pct { object-position: 25% 75%; } .edge { object-position: right 0.1in bottom 0.2in; }",
        );
        let root = resolver.default_style();
        let body_info = element("body", None, &[]);
        let body_style = resolver.compute_style(&body_info, &root, None, &[]);
        let inherited = resolver.compute_style(
            &element("img", None, &[]),
            &body_style,
            None,
            &[body_info.clone()],
        );
        assert_eq!(
            inherited.object_position.x,
            BackgroundPositionComponent::End(LengthSpec::Absolute(Pt::ZERO))
        );
        assert_eq!(
            inherited.object_position.y,
            BackgroundPositionComponent::Start(LengthSpec::Absolute(Pt::ZERO))
        );

        let pct = resolver.compute_style(&element("img", None, &["pct"]), &body_style, None, &[]);
        assert_eq!(
            pct.object_position.x,
            BackgroundPositionComponent::Start(LengthSpec::Percent(0.25))
        );
        assert_eq!(
            pct.object_position.y,
            BackgroundPositionComponent::Start(LengthSpec::Percent(0.75))
        );

        let edge = resolver.compute_style(&element("img", None, &["edge"]), &body_style, None, &[]);
        assert_eq!(
            edge.object_position.x,
            BackgroundPositionComponent::End(length_spec_from_string("0.1in").unwrap())
        );
        assert_eq!(
            edge.object_position.y,
            BackgroundPositionComponent::End(length_spec_from_string("0.2in").unwrap())
        );
    }

    #[test]
    fn radial_gradient_background_sets_background_paint() {
        let direct = parse_background_paint_str(
            "radial-gradient(circle at 10% 0%, #1d2f6d 0%, #0c1430 48%, #070b19 100%)",
        );
        match direct {
            Some(BackgroundPaint::RadialGradient {
                center_x_pct,
                center_y_pct,
                ..
            }) => {
                assert!(
                    (center_x_pct - 0.10).abs() < 0.01,
                    "direct parse center_x_pct={center_x_pct}"
                );
                assert!(
                    (center_y_pct - 0.00).abs() < 0.01,
                    "direct parse center_y_pct={center_y_pct}"
                );
            }
            other => panic!("expected direct radial parse, got {other:?}"),
        }
        let resolver = StyleResolver::new(
            ".x { background: radial-gradient(circle at 10% 0%, #1d2f6d 0%, #0c1430 48%, #070b19 100%); }",
        );
        let root = resolver.default_style();
        let info = element("div", None, &["x"]);
        let style = resolver.compute_style(&info, &root, None, &[]);
        match style.background_paint {
            Some(BackgroundPaint::RadialGradient {
                center_x_pct,
                center_y_pct,
                stops,
            }) => {
                assert!(
                    (center_x_pct - 0.10).abs() < 0.01,
                    "unexpected center_x_pct={center_x_pct}"
                );
                assert!(
                    (center_y_pct - 0.00).abs() < 0.01,
                    "unexpected center_y_pct={center_y_pct}"
                );
                assert_eq!(stops.len(), 3);
                assert!((stops[0].offset - 0.0).abs() < 0.001);
                assert!((stops[1].offset - 0.48).abs() < 0.01);
                assert!((stops[2].offset - 1.0).abs() < 0.001);
            }
            other => panic!("expected radial background paint, got {other:?}"),
        }
    }

    #[test]
    fn radial_gradient_background_with_var_stop_resolves() {
        let css = ":root { --bg0: #0c1430; } .x { background: radial-gradient(circle at 10% 0%, #1d2f6d 0%, var(--bg0) 48%, #070b19 100%); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let mut root_info = element("html", None, &[]);
        root_info.is_root = true;
        let root_style = resolver.compute_style(&root_info, &root, None, &[]);
        let info = element("div", None, &["x"]);
        let style = resolver.compute_style(&info, &root_style, None, &[root_info]);
        match style.background_paint {
            Some(BackgroundPaint::RadialGradient {
                center_x_pct,
                center_y_pct,
                stops,
            }) => {
                assert!(
                    (center_x_pct - 0.10).abs() < 0.01,
                    "unexpected center_x_pct={center_x_pct}"
                );
                assert!(
                    (center_y_pct - 0.00).abs() < 0.01,
                    "unexpected center_y_pct={center_y_pct}"
                );
                assert_eq!(stops.len(), 3);
                assert!(
                    (stops[1].color.r - (12.0 / 255.0)).abs() < 0.01
                        && (stops[1].color.g - (20.0 / 255.0)).abs() < 0.01
                        && (stops[1].color.b - (48.0 / 255.0)).abs() < 0.01,
                    "expected var-resolved middle stop, got {:?}",
                    stops[1].color
                );
            }
            other => panic!("expected radial background paint, got {other:?}"),
        }
    }

    #[test]
    fn display_table_is_not_normalized() {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        let path = std::env::temp_dir().join(format!(
            "fullbleed_style_layout_known_loss_{}_{}.jsonl",
            std::process::id(),
            nanos
        ));
        let logger = Arc::new(DebugLogger::new(&path).expect("debug logger"));
        let resolver =
            StyleResolver::new_with_debug(".menu { display: table; }", Some(logger.clone()));
        drop(resolver);
        drop(logger);
        let log = std::fs::read_to_string(&path).expect("read debug log");
        assert!(
            !log.contains("\"LAYOUT_MODE_NORMALIZED\""),
            "display:table should be preserved, log={log}"
        );
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn unsupported_ruby_and_legacy_box_layouts_are_normalized_and_logged() {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        let path = std::env::temp_dir().join(format!(
            "fullbleed_style_layout_normalized_{}_{}.jsonl",
            std::process::id(),
            nanos
        ));
        let logger = Arc::new(DebugLogger::new(&path).expect("debug logger"));
        let resolver = StyleResolver::new_with_debug(
            ".ruby { display: inline ruby; } .legacy { display: -webkit-box; }",
            Some(logger.clone()),
        );
        drop(resolver);
        drop(logger);
        let log = std::fs::read_to_string(&path).expect("read debug log");
        assert_eq!(
            log.matches("\"LAYOUT_MODE_NORMALIZED\"").count(),
            2,
            "{log}"
        );
        assert!(
            log.contains("\"requested\":\"inline ruby\",\"applied\":\"inline\"")
                && log.contains("\"reason\":\"display_ruby_not_supported\""),
            "missing ruby normalization: {log}"
        );
        assert!(
            log.contains("\"requested\":\"-webkit-box\",\"applied\":\"block\"")
                && log.contains("\"reason\":\"display_legacy_box_not_supported\""),
            "missing legacy-box normalization: {log}"
        );
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn grid_template_columns_sets_column_count() {
        let resolver =
            StyleResolver::new(".menu { display: grid; grid-template-columns: 1fr 1fr 1fr; }");
        let root = resolver.default_style();
        let info = element("div", None, &["menu"]);
        let style = resolver.compute_style(&info, &root, None, &[]);
        assert_eq!(style.display, DisplayMode::Grid);
        assert_eq!(style.grid_columns, Some(3));
        assert_eq!(
            style.grid_column_tracks,
            vec![
                GridTrackSize::fraction(1.0),
                GridTrackSize::fraction(1.0),
                GridTrackSize::fraction(1.0),
            ]
        );
    }

    #[test]
    fn two_keyword_display_syntax_preserves_inner_layout_mode() {
        let resolver = StyleResolver::new(
            ".bf { display: block flex; } .if { display: inline flex; } \
             .bg { display: block grid; } .ig { display: inline grid; }",
        );
        let root = resolver.default_style();
        let computed =
            |class| resolver.compute_style(&element("div", None, &[class]), &root, None, &[]);

        assert_eq!(computed("bf").display, DisplayMode::Flex);
        assert_eq!(computed("if").display, DisplayMode::InlineFlex);
        assert_eq!(computed("bg").display, DisplayMode::Grid);
        assert_eq!(computed("ig").display, DisplayMode::InlineGrid);
    }

