    #[test]
    fn grid_start_lines_parse_from_longhands_and_shorthands() {
        let resolver = StyleResolver::new(
            ".a{grid-column-start:2;grid-row-start:3}.b{grid-column:4/6;grid-row:5/8}.c{grid-area:7/8/span 2/span 1}",
        );
        let root = resolver.default_style();
        let a = resolver.compute_style(&element("div", None, &["a"]), &root, None, &[]);
        let b = resolver.compute_style(&element("div", None, &["b"]), &root, None, &[]);
        let c = resolver.compute_style(&element("div", None, &["c"]), &root, None, &[]);

        assert_eq!(a.grid_column_start, Some(2));
        assert_eq!(a.grid_row_start, Some(3));
        assert_eq!(b.grid_column_start, Some(4));
        assert_eq!(b.grid_row_start, Some(5));
        assert_eq!(c.grid_row_start, Some(7));
        assert_eq!(c.grid_column_start, Some(8));
    }

    #[test]
    fn display_table_keywords_map_to_table_modes() {
        let resolver = StyleResolver::new(
            ".t{display:table}.it{display:inline-table}.tr{display:table-row}.tc{display:table-cell}.tcg{display:table-column-group}.tcol{display:table-column}.th{display:table-header-group}",
        );
        let root = resolver.default_style();
        let t = resolver.compute_style(&element("div", None, &["t"]), &root, None, &[]);
        let it = resolver.compute_style(&element("div", None, &["it"]), &root, None, &[]);
        let tr = resolver.compute_style(&element("div", None, &["tr"]), &root, None, &[]);
        let tc = resolver.compute_style(&element("div", None, &["tc"]), &root, None, &[]);
        let tcg = resolver.compute_style(&element("div", None, &["tcg"]), &root, None, &[]);
        let tcol = resolver.compute_style(&element("div", None, &["tcol"]), &root, None, &[]);
        let th = resolver.compute_style(&element("div", None, &["th"]), &root, None, &[]);
        assert_eq!(t.display, DisplayMode::Table);
        assert_eq!(it.display, DisplayMode::InlineTable);
        assert_eq!(tr.display, DisplayMode::TableRow);
        assert_eq!(tc.display, DisplayMode::TableCell);
        assert_eq!(tcg.display, DisplayMode::TableColumnGroup);
        assert_eq!(tcol.display, DisplayMode::TableColumn);
        assert_eq!(th.display, DisplayMode::TableHeaderGroup);
    }

    #[test]
    fn display_list_item_keywords_map_to_list_item_modes() {
        let resolver = StyleResolver::new(
            ".li{display:list-item}.ili{display:inline list-item}.bli{display:block list-item}",
        );
        let root = resolver.default_style();
        let li = resolver.compute_style(&element("div", None, &["li"]), &root, None, &[]);
        let ili = resolver.compute_style(&element("div", None, &["ili"]), &root, None, &[]);
        let bli = resolver.compute_style(&element("div", None, &["bli"]), &root, None, &[]);
        assert_eq!(li.display, DisplayMode::ListItem);
        assert_eq!(ili.display, DisplayMode::InlineListItem);
        assert_eq!(bli.display, DisplayMode::ListItem);
    }

    #[test]
