    #[test]
    fn font_size_resolves_keywords_vars_and_invalid_negative_values() {
        let css = concat!(
            "body { --fs: larger; --bad: -5px; font-size: 20px; }",
            ".small { font-size: small; }",
            ".larger { font-size: larger; }",
            ".smaller { font-size: smaller; }",
            ".percent { font-size: 80%; }",
            ".em { font-size: 1.5em; }",
            ".rem { font-size: 1.5rem; }",
            ".var { font-size: var(--fs); }",
            ".fallback { font-size: var(--missing, 150%); }",
            ".initial { font-size: initial; }",
            ".invalid { font-size: 30px; font-size: var(--bad); }"
        );
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let body_info = element("body", None, &[]);
        let body_style = resolver.compute_style(&body_info, &root, None, &[]);
        let ancestors = [body_info];

        let font_size_for = |class_name: &str| {
            let info = element("p", None, &[class_name]);
            resolver
                .compute_style(&info, &body_style, None, &ancestors)
                .font_size
                .to_f32()
        };

        assert!((font_size_for("small") - 9.75).abs() < 0.01);
        assert!((font_size_for("larger") - 18.0).abs() < 0.01);
        assert!((font_size_for("smaller") - 12.0).abs() < 0.01);
        assert!((font_size_for("percent") - 12.0).abs() < 0.01);
        assert!((font_size_for("em") - 22.5).abs() < 0.01);
        assert!((font_size_for("rem") - 18.0).abs() < 0.01);
        assert!((font_size_for("var") - 18.0).abs() < 0.01);
        assert!((font_size_for("fallback") - 22.5).abs() < 0.01);
        assert!((font_size_for("initial") - 12.0).abs() < 0.01);
        assert!((font_size_for("invalid") - 15.0).abs() < 0.01);
    }

    #[test]
    fn line_height_distinguishes_unitless_from_computed_lengths() {
        let css = concat!(
            ":root { font-size: 16px; }",
            "body { --lh: 150%; --bad: -1; font-size: 20px; line-height: normal; }",
            ".number { line-height: 1.5; }",
            ".percent { line-height: 150%; }",
            ".em { line-height: 1.5em; }",
            ".rem { line-height: 1.5rem; }",
            ".var { line-height: var(--lh); }",
            ".fallback { line-height: var(--missing, 2); }",
            ".initial { line-height: initial; }",
            ".invalid { line-height: 30pt; line-height: var(--bad); }",
            ".parent-length { line-height: 1.5em; }",
            ".parent-number { line-height: 1.5; }",
            ".child { font-size: 30pt; line-height: inherit; }"
        );
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let mut root_info = element("html", None, &[]);
        root_info.is_root = true;
        let root_style = resolver.compute_style(&root_info, &root, None, &[]);
        let body_info = element("body", None, &[]);
        let body_style =
            resolver.compute_style(&body_info, &root_style, None, &[root_info.clone()]);
        let ancestors = [root_info, body_info.clone()];

        let line_height_for = |class_name: &str| {
            let info = element("p", None, &[class_name]);
            let style = resolver.compute_style(&info, &body_style, None, &ancestors);
            style.line_height.to_line_height(style.font_size).to_f32()
        };

        assert!((line_height_for("number") - 22.5).abs() < 0.01);
        assert!((line_height_for("percent") - 22.5).abs() < 0.01);
        assert!((line_height_for("em") - 22.5).abs() < 0.01);
        assert!((line_height_for("rem") - 18.0).abs() < 0.01);
        assert!((line_height_for("var") - 22.5).abs() < 0.01);
        assert!((line_height_for("fallback") - 30.0).abs() < 0.01);
        assert!((line_height_for("initial") - 18.0).abs() < 0.01);
        assert!((line_height_for("invalid") - 18.0).abs() < 0.01);

        let parent_length_info = element("section", None, &["parent-length"]);
        let parent_length =
            resolver.compute_style(&parent_length_info, &body_style, None, &ancestors);
        let child_info = element("p", None, &["child"]);
        let child_length = resolver.compute_style(
            &child_info,
            &parent_length,
            None,
            &[body_info.clone(), parent_length_info],
        );
        assert!((child_length.font_size.to_f32() - 30.0).abs() < 0.01);
        assert!(
            (child_length
                .line_height
                .to_line_height(child_length.font_size)
                .to_f32()
                - 22.5)
                .abs()
                < 0.01
        );

        let parent_number_info = element("section", None, &["parent-number"]);
        let parent_number =
            resolver.compute_style(&parent_number_info, &body_style, None, &ancestors);
        let child_number = resolver.compute_style(
            &child_info,
            &parent_number,
            None,
            &[body_info, parent_number_info],
        );
        assert!(
            (child_number
                .line_height
                .to_line_height(child_number.font_size)
                .to_f32()
                - 45.0)
                .abs()
                < 0.01
        );
    }

