        let css = ".parent { writing-mode: vertical-rl; } .child { margin-inline-start: 0.25in; margin-inline-end: 0.125in; margin-block-start: 0.375in; margin-block-end: 0.5in; padding-inline-start: 0.25in; padding-inline-end: 0.125in; padding-block-start: 0.375in; padding-block-end: 0.5in; }";
