        let style = resolver.compute_style(&child_info, &parent_style, None, &[parent_info]);

        assert_eq!(style.writing_mode, WritingModeMode::VerticalRl);
        assert_eq!(style.margin.top, LengthSpec::Absolute(Pt::from_f32(18.0)));
        assert_eq!(style.margin.right, LengthSpec::Absolute(Pt::from_f32(27.0)));
        assert_eq!(style.margin.bottom, LengthSpec::Absolute(Pt::from_f32(9.0)));
