    #[test]
    fn text_underline_position_parses_keyword_combinations_and_vars() {
        let css = ".under { text-underline-position: under; } .left { text-underline-position: left; } .combo { text-underline-position: right under; } .font { text-underline-position: from-font left; } .var { --pos: under right; text-underline-position: var(--pos); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let under = resolver.compute_style(&element("div", None, &["under"]), &root, None, &[]);
        assert_eq!(
            under.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Under,
                side: None
            }
        );

        let left = resolver.compute_style(&element("div", None, &["left"]), &root, None, &[]);
        assert_eq!(
            left.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Auto,
                side: Some(TextUnderlinePositionSide::Left)
            }
        );

        let combo = resolver.compute_style(&element("div", None, &["combo"]), &root, None, &[]);
        assert_eq!(
            combo.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Under,
                side: Some(TextUnderlinePositionSide::Right)
            }
        );

        let font = resolver.compute_style(&element("div", None, &["font"]), &root, None, &[]);
        assert_eq!(
            font.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::FromFont,
                side: Some(TextUnderlinePositionSide::Left)
            }
        );

        let var = resolver.compute_style(&element("div", None, &["var"]), &root, None, &[]);
        assert_eq!(
            var.text_underline_position,
            TextUnderlinePositionMode {
                line: TextUnderlinePositionLine::Under,
                side: Some(TextUnderlinePositionSide::Right)
            }
        );
    }

