    #[test]
    fn text_shadow_parses_lists_currentcolor_and_vars() {
        let css = ".current { color: rgb(0, 128, 0); text-shadow: 12px 0 0 currentColor; } .multi { text-shadow: red 3px 4px, 0 0 2px blue; } .var { --shadow: 2px 0 0 rgb(160, 0, 210); text-shadow: var(--shadow); } .colorvar { --shade: rgb(255, 128, 0); text-shadow: 1em -0.5em 0.25em var(--shade); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let current = resolver.compute_style(&element("div", None, &["current"]), &root, None, &[]);
        assert_eq!(current.text_shadows.len(), 1);
        assert_eq!(
            current.text_shadows[0].offset_x,
            LengthSpec::Absolute(px_to_pt(12.0))
        );
        assert!((current.text_shadows[0].color.g - (128.0 / 255.0)).abs() < 0.001);
        assert!(current.text_shadows[0].color_var.is_none());

        let multi = resolver.compute_style(&element("div", None, &["multi"]), &root, None, &[]);
        assert_eq!(multi.text_shadows.len(), 2);
        assert_eq!(
            multi.text_shadows[0].offset_x,
            LengthSpec::Absolute(px_to_pt(3.0))
        );
        assert_eq!(
            multi.text_shadows[0].offset_y,
            LengthSpec::Absolute(px_to_pt(4.0))
        );
        assert!(multi.text_shadows[0].color.r > 0.99);
        assert_eq!(
            multi.text_shadows[1].blur,
            LengthSpec::Absolute(px_to_pt(2.0))
        );
        assert!(multi.text_shadows[1].color.b > 0.99);

        let var = resolver.compute_style(&element("div", None, &["var"]), &root, None, &[]);
        assert_eq!(var.text_shadows.len(), 1);
        assert_eq!(
            var.text_shadows[0].offset_x,
            LengthSpec::Absolute(px_to_pt(2.0))
        );
        assert!((var.text_shadows[0].color.r - (160.0 / 255.0)).abs() < 0.001);
        assert!((var.text_shadows[0].color.b - (210.0 / 255.0)).abs() < 0.001);

        let colorvar =
            resolver.compute_style(&element("div", None, &["colorvar"]), &root, None, &[]);
        assert_eq!(colorvar.text_shadows.len(), 1);
        assert_eq!(colorvar.text_shadows[0].offset_x, LengthSpec::Em(1.0));
        assert_eq!(colorvar.text_shadows[0].offset_y, LengthSpec::Em(-0.5));
        assert_eq!(colorvar.text_shadows[0].blur, LengthSpec::Em(0.25));
        assert!((colorvar.text_shadows[0].color.g - (128.0 / 255.0)).abs() < 0.001);
        assert!(colorvar.text_shadows[0].color_var.is_none());
    }

    #[test]
    fn text_shadow_inherits_and_initial_resets_to_none() {
        let css = ".parent { text-shadow: 6px 0 0 rgb(0, 0, 255); } .unset { text-shadow: unset; } .initial { text-shadow: initial; }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let parent_info = element("div", None, &["parent"]);
        let parent_style = resolver.compute_style(&parent_info, &root, None, &[]);
        assert_eq!(parent_style.text_shadows.len(), 1);

        let child = resolver.compute_style(
            &element("span", None, &[]),
            &parent_style,
            None,
            &[parent_info.clone()],
        );
        assert_eq!(child.text_shadows.len(), 1);
        assert!(child.text_shadows[0].color.b > 0.99);

        let unset = resolver.compute_style(
            &element("span", None, &["unset"]),
            &parent_style,
            None,
            &[parent_info.clone()],
        );
        assert_eq!(unset.text_shadows.len(), 1);

        let initial = resolver.compute_style(
            &element("span", None, &["initial"]),
            &parent_style,
            None,
            &[parent_info],
        );
        assert!(initial.text_shadows.is_empty());
    }

    #[test]
    fn line_break_parses_keywords_inheritance_and_vars() {
        let css = ".anywhere { line-break: anywhere; } .loose { line-break: loose; } .parent { line-break: strict; } .unset { line-break: unset; } .initial { line-break: initial; } .var { --lb: anywhere; line-break: var(--lb); } .fallback { line-break: var(--missing, normal); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let anywhere =
            resolver.compute_style(&element("div", None, &["anywhere"]), &root, None, &[]);
        assert_eq!(anywhere.line_break, LineBreakMode::Anywhere);

        let loose = resolver.compute_style(&element("div", None, &["loose"]), &root, None, &[]);
        assert_eq!(loose.line_break, LineBreakMode::Loose);

        let parent_info = element("div", None, &["parent"]);
        let parent_style = resolver.compute_style(&parent_info, &root, None, &[]);
        assert_eq!(parent_style.line_break, LineBreakMode::Strict);

        let inherited = resolver.compute_style(
            &element("span", None, &[]),
            &parent_style,
            None,
            &[parent_info.clone()],
        );
        assert_eq!(inherited.line_break, LineBreakMode::Strict);

        let unset = resolver.compute_style(
            &element("span", None, &["unset"]),
            &parent_style,
            None,
            &[parent_info.clone()],
        );
        assert_eq!(unset.line_break, LineBreakMode::Strict);

        let initial = resolver.compute_style(
            &element("span", None, &["initial"]),
            &parent_style,
            None,
            &[parent_info],
        );
        assert_eq!(initial.line_break, LineBreakMode::Auto);

        let var = resolver.compute_style(&element("div", None, &["var"]), &root, None, &[]);
        assert_eq!(var.line_break, LineBreakMode::Anywhere);

        let fallback =
            resolver.compute_style(&element("div", None, &["fallback"]), &root, None, &[]);
        assert_eq!(fallback.line_break, LineBreakMode::Normal);
    }

