    #[test]
    fn list_style_type_preserves_symbols_function_markers() {
        let css = ".symbolic { list-style-type: symbols(\"*\" \"+\"); } \
                   .cyclic { list-style-type: symbols(cyclic \"*\" \"+\"); } \
                   .numeric { list-style-type: symbols(numeric \"0\" \"1\"); } \
                   .alphabetic { list-style-type: symbols(alphabetic \"A\" \"B\"); }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();

        let symbolic =
            resolver.compute_style(&element("li", None, &["symbolic"]), &root, None, &[]);
        let cyclic = resolver.compute_style(&element("li", None, &["cyclic"]), &root, None, &[]);
        let numeric = resolver.compute_style(&element("li", None, &["numeric"]), &root, None, &[]);
        let alphabetic =
            resolver.compute_style(&element("li", None, &["alphabetic"]), &root, None, &[]);

        assert_eq!(
            symbolic.list_style_type,
            ListStyleTypeMode::AnonymousSymbols
        );
        assert_eq!(
            symbolic
                .list_style_symbols
                .as_ref()
                .map(|symbols| symbols.system),
            Some(AnonymousListStyleSymbolsSystem::Symbolic)
        );
        assert_eq!(cyclic.list_style_type, ListStyleTypeMode::AnonymousSymbols);
        assert_eq!(
            cyclic
                .list_style_symbols
                .as_ref()
                .map(|symbols| symbols.system),
            Some(AnonymousListStyleSymbolsSystem::Cyclic)
        );
        assert_eq!(numeric.list_style_type, ListStyleTypeMode::AnonymousSymbols);
        assert_eq!(
            numeric
                .list_style_symbols
                .as_ref()
                .map(|symbols| symbols.system),
            Some(AnonymousListStyleSymbolsSystem::Numeric)
        );
        assert_eq!(
            alphabetic.list_style_type,
            ListStyleTypeMode::AnonymousSymbols
        );
        assert_eq!(
            alphabetic
                .list_style_symbols
                .as_ref()
                .map(|symbols| symbols.system),
            Some(AnonymousListStyleSymbolsSystem::Alphabetic)
        );
    }

