        assert_eq!(
            style.border_width.right,
            LengthSpec::Absolute(Pt::from_f32(2.25))
        );
        assert_eq!(
            style.border_width.bottom,
            LengthSpec::Absolute(Pt::from_f32(3.75))
        );
