    #[test]
    fn direction_rtl_remaps_logical_inline_border_edges() {
        let css = ".parent { direction: rtl; } .child { border-inline-start: 4px solid red; border-inline-end: 2px solid blue; }";
        let resolver = StyleResolver::new(css);
        let root = resolver.default_style();
        let parent_info = element("div", None, &["parent"]);
        let parent_style = resolver.compute_style(&parent_info, &root, None, &[]);
        let child_info = element("div", None, &["child"]);
        let style = resolver.compute_style(&child_info, &parent_style, None, &[parent_info]);

        assert_eq!(style.direction, DirectionMode::Rtl);
        assert_eq!(style.border_width.top, LengthSpec::Absolute(Pt::ZERO));
        assert_eq!(
            style.border_width.right,
            LengthSpec::Absolute(Pt::from_f32(3.0))
        );
        assert_eq!(style.border_width.bottom, LengthSpec::Absolute(Pt::ZERO));
        assert_eq!(
            style.border_width.left,
            LengthSpec::Absolute(Pt::from_f32(1.5))
        );
        assert_eq!(style.border_right_color, Some(Color::rgb(1.0, 0.0, 0.0)));
        assert_eq!(style.border_left_color, Some(Color::rgb(0.0, 0.0, 1.0)));
        assert!(style.border_color.is_none());
    }

